import { Effect, Schedule } from "effect"

export interface PackageManifest {
  readonly name: string
  readonly version: string
  readonly tarball: string
}

export class RegistryError extends Error {
  readonly _tag = "RegistryError"

  constructor(readonly status: number, message: string) {
    super(message)
  }
}

const isTransient = (error: RegistryError) =>
  error.status === 429 || error.status >= 500

const requestManifest = (name: string) =>
  Effect.tryPromise({
    try: async () => {
      const response = await fetch(
        `https://registry.internal/packages/${encodeURIComponent(name)}/manifest`
      )
      if (!response.ok) {
        throw new RegistryError(response.status, `Cannot load ${name}`)
      }
      return (await response.json()) as PackageManifest
    },
    catch: (error) =>
      error instanceof RegistryError
        ? error
        : new RegistryError(0, String(error))
  })

export const fetchPackageManifest = (
  name: string
): Effect.Effect<PackageManifest, RegistryError> =>
  requestManifest(name).pipe(
    Effect.retry({
      times: 3,
      while: isTransient,
      schedule: Schedule.exponential("150 millis")
    })
  )
